publicRouter.get("/n8n/health", async (req, res) => {
  const n8nUrl = (process.env.N8N_PUBLIC_URL || process.env.VITE_N8N_URL || process.env.N8N_BASE_URL || "https://n8n.webtrionix.com").replace(/\/$/, "");
  const apiKey = process.env.N8N_API_KEY || "";
  const start = performance.now();
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6e3);
    const r2 = await fetch(`${n8nUrl}/healthz`, {
      headers: { "X-N8N-API-KEY": apiKey },
      signal: controller.signal
    });
    clearTimeout(timeout);
    const latencyMs = Math.round(performance.now() - start);
    if (r2.status === 401) {
      return res.status(401).json({
        reachable: false,
        status: "unauthorized",
        latencyMs,
        error: "Invalid N8N_API_KEY (HTTP 401 Unauthorized)",
        url: n8nUrl
      });
    }
    if (!r2.ok) {
      return res.status(r2.status).json({
        reachable: false,
        status: "error",
        latencyMs,
        error: `n8n returned HTTP ${r2.status}`,
        url: n8nUrl
      });
    }
    return res.json({
      reachable: true,
      status: "ok",
      latencyMs,
      url: n8nUrl,
      version: "2.44.4"
    });
  } catch (err) {
    const latencyMs = Math.round(performance.now() - start);
    return res.status(503).json({
      reachable: false,
      status: "unreachable",
      latencyMs,
      error: `Connection error: n8n instance or tunnel is unreachable (${err.message})`,
      url: n8nUrl
    });
  }
});
