function formatPostRow(r2) {
  let targets = [];
  try {
    targets = typeof r2.targets_json === "string" ? JSON.parse(r2.targets_json || "[]") : r2.targets || [];
  } catch {
  }
  const primaryTarget = targets[0] || {};
  const zoneInfo = toZone(r2.scheduled_utc, r2.timezone);
  let mediaUrls = [];
  try {
    mediaUrls = JSON.parse(r2.media_urls || "[]");
  } catch {
    mediaUrls = r2.media_urls ? [r2.media_urls] : [];
  }
  let commentsCount = 0;
  try {
    const cRes = db.prepare("SELECT count(*) as c FROM post_comments WHERE post_id = ?").get(r2.post_id);
    if (cRes) commentsCount = cRes.c;
  } catch {
  }
  let approvalStatus = "draft";
  if (r2.approval_status === "Approved") approvalStatus = "approved";
  else if (r2.approval_status === "PendingApproval" || r2.approval_status === "in_review") approvalStatus = "in_review";
  else if (r2.approval_status === "ChangesRequested" || r2.approval_status === "revision_requested") approvalStatus = "revision_requested";
  else if (r2.approval_status === "Rejected" || r2.approval_status === "rejected") approvalStatus = "rejected";
  const allPosted = targets.length > 0 && targets.every((t2) => t2.status === "Posted");
  const anyFailed = targets.some((t2) => t2.status === "Failed");
  const anyPartial = targets.some((t2) => t2.status === "NeedsVerification" || t2.error_code === "WARN_PARTIAL" || t2.error_message && t2.error_message.includes("FAILED"));
  const anyRetrying = targets.some((t2) => t2.status === "Retrying");
  const pubStatus = anyPartial ? "partial" : allPosted ? "published" : anyRetrying ? "retrying" : anyFailed ? "failed" : primaryTarget.status ? primaryTarget.status.toLowerCase() : "scheduled";
  const latestPostedAt = targets.find((t2) => t2.posted_at)?.posted_at || primaryTarget.posted_at;
  const combinedError = targets.map((t2) => t2.error_message).filter(Boolean).join("; ") || null;
  return {
    id: r2.post_id,
    postId: r2.post_id,
    brandId: r2.brand_id,
    brandName: r2.brand_name || "Flower Plant",
    createdByUserId: 1,
    createdByName: r2.approved_by || "David Vance",
    assignedApproverId: 3,
    assignedApproverName: "Marcus Approver",
    title: r2.title,
    masterCaption: r2.caption,
    hashtags: r2.hashtags ? Array.isArray(r2.hashtags) ? r2.hashtags : r2.hashtags.split(" ").filter(Boolean) : [],
    media: mediaUrls.map((u) => ({ fileUrl: u, mediaType: r2.media_type || "image" })),
    platforms: targets.map((t2) => ({
      platform: t2.platform,
      publishingStatus: t2.status || "scheduled",
      publishedUrl: t2.post_url,
      platformPostId: t2.platform_post_id,
      errorMessage: t2.error_message,
      errorCode: t2.error_code
    })),
    scheduledAt: r2.scheduled_utc,
    scheduledAtDisplay: zoneInfo.displayDateTime,
    publishedAt: latestPostedAt,
    approvalStatus,
    publishingStatus: pubStatus === "posted" ? "published" : pubStatus,
    errorMessage: combinedError,
    timezone: r2.timezone,
    source: r2.source || "dashboard",
    placement: r2.placement ? typeof r2.placement === "string" ? JSON.parse(r2.placement) : r2.placement : ["feed"],
    placements: r2.placement ? typeof r2.placement === "string" ? JSON.parse(r2.placement) : r2.placement : ["feed"],
    taggedUsers: r2.tagged_users ? typeof r2.tagged_users === "string" ? JSON.parse(r2.tagged_users || "[]") : r2.tagged_users : [],
    versionNumber: r2.version || 1,
    version: r2.version || 1,
    commentsCount,
    createdAt: r2.created_at,
    updatedAt: r2.updated_at,
    targets
  };
}
function getFormattedPostById(postId) {
  const query = `
    SELECT p.*, b.brand_name,
           (SELECT json_group_array(json_object(
             'target_id', t.target_id,
             'platform', t.platform,
             'status', t.status,
             'attempt_count', t.attempt_count,
             'platform_post_id', t.platform_post_id,
             'post_url', t.post_url,
             'posted_at', t.posted_at,
             'error_code', t.error_code,
             'error_message', t.error_message
           )) FROM post_targets t WHERE t.post_id = p.post_id) as targets_json
    FROM posts p
    LEFT JOIN brands b ON p.brand_id = b.brand_id
    WHERE p.post_id = ?
  `;
  const row = db.prepare(query).get(postId);
  return row ? formatPostRow(row) : null;
}
publicRouter.get("/posts", (req, res) => {
  const clientId = req.query.clientId || DEFAULT_CLIENT_ID;
  const status = req.query.status;
  let query = `
    SELECT p.*, b.brand_name,
           (SELECT json_group_array(json_object(
             'target_id', t.target_id,
             'platform', t.platform,
             'status', t.status,
             'attempt_count', t.attempt_count,
             'platform_post_id', t.platform_post_id,
             'post_url', t.post_url,
             'posted_at', t.posted_at,
             'error_code', t.error_code,
             'error_message', t.error_message
           )) FROM post_targets t WHERE t.post_id = p.post_id) as targets_json
    FROM posts p
    LEFT JOIN brands b ON p.brand_id = b.brand_id
    WHERE p.client_id = ? AND p.deleted_at IS NULL
  `;
  const params = [clientId];
  if (status) {
    query += ` AND p.approval_status = ?`;
    params.push(status);
  }
  query += ` ORDER BY p.scheduled_utc DESC LIMIT 100`;
  const rows = db.prepare(query).all(...params);
  const posts = rows.map(formatPostRow);
  return res.json({ data: posts });
});
publicRouter.get("/posts/:id", (req, res) => {
  const post = db.prepare(`
    SELECT p.*, b.brand_name
    FROM posts p
    JOIN brands b ON p.brand_id = b.brand_id
    WHERE p.post_id = ? AND p.deleted_at IS NULL
  `).get(req.params.id);
  if (!post) {
    return res.status(404).json({ error: { code: "POST_NOT_FOUND", message: "Post not found" } });
  }
  const targets = db.prepare(`SELECT * FROM post_targets WHERE post_id = ?`).all(post.post_id);
  const attempts = db.prepare(`
    SELECT a.* FROM publish_attempts a
    JOIN post_targets t ON a.target_id = t.target_id
    WHERE t.post_id = ? ORDER BY a.started_at DESC
  `).all(post.post_id);
  return res.json({ data: { post, targets, attempts } });
});
